<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { ArrowLeft, ArrowUpRight, Search, RefreshCw, Clock3, Play, CircleAlert, Check, X, Send, FileText, ExternalLink, LoaderCircle, Ban, ChevronLeft, ChevronRight } from '@lucide/vue';
import TaskUsage from '../../components/TaskUsage.vue';
import TaskDelivery from '../../components/TaskDelivery.vue';
import type { UsageEntry } from '../../../../shared/billing';
import BaseSelect from '../../components/BaseSelect.vue';
import { api, message, formatDate, go } from '../../api';
import { refresh, workspace, scopeName } from './common';
import { taskStatusNames, scenarios, type AutomationTask, type InputVersion } from '../../../../shared/automation';
const props=defineProps<{id?:string;reports?:boolean}>();
const query=ref(''),filter=ref(''),kind=ref(''),error=ref(''),busy=ref(false),page=ref(1),detail=ref<AutomationTask|null>(null),version=ref<InputVersion|null>(null);
const usageEntries=ref<UsageEntry[]>([]);
const events=ref<{seq:number;time:number;message:string}[]>([]);const followDialog=ref<HTMLDialogElement>();const requirements=ref(''),followKind=ref<'generation'|'evaluation'>('generation');
const tab=ref('report');const siteFilter=new URLSearchParams(window.location.hash.split('?')[1]||'').get('site');
const list=computed(()=>workspace.tasks.filter(t=>(!props.reports||t.kind==='evaluation')&&(!siteFilter||t.generatedSiteId===siteFilter)&&(!kind.value||t.kind===kind.value)&&(!filter.value||(filter.value==='attention'?(['pending','interrupted'].includes(t.status)||t.delivery&&['uncertain','failed'].includes(t.delivery.status)):t.status===filter.value))&&(!query.value||[t.resourceName,t.siteUrl,t.id].join(' ').toLowerCase().includes(query.value.toLowerCase()))));
const pages=computed(()=>Math.max(1,Math.ceil(list.value.length/20)));const rows=computed(()=>list.value.slice((page.value-1)*20,page.value*20));
const active=computed(()=>workspace.tasks.filter(t=>!t.stopped&&t.status!=='following-up'));const queued=computed(()=>workspace.tasks.filter(t=>t.status==='queued').length);const pending=computed(()=>workspace.tasks.filter(t=>['pending','interrupted'].includes(t.status)||t.delivery&&['uncertain','failed'].includes(t.delivery.status)).length);
let timer:ReturnType<typeof setInterval>;let disposed=false;let loading=false;
async function load(){if(loading)return;loading=true;try{await refresh();if(props.id){const r=await api<{task:AutomationTask;usageEntries:UsageEntry[];childUsageEntries:UsageEntry[];events:typeof events.value;version:InputVersion}>(`/automation/tasks/${props.id}`);if(!disposed){detail.value=r.task;usageEntries.value=[...(r.usageEntries||[]),...(r.childUsageEntries||[])];events.value=r.events;version.value=r.version;}}}catch(e){if(!disposed)error.value=message(e);}finally{loading=false;}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),4000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});watch(()=>props.id,()=>{detail.value=null;error.value='';void load();});watch([query,filter,kind],()=>page.value=1);watch(pages,v=>page.value=Math.min(page.value,v));
async function cancel(){if(!detail.value)return;busy.value=true;error.value='';try{await api(`/automation/tasks/${detail.value.id}/cancel`,{method:'POST'});await load();}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function resume(){if(!detail.value)return;busy.value=true;error.value='';try{await api(`/automation/tasks/${detail.value.id}/resume`,{method:'POST'});await load();}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function confirmStopped(){if(!detail.value)return;busy.value=true;try{await api(`/automation/tasks/${detail.value.id}/confirm-stopped`,{method:'POST'});await load();}catch(e){error.value=message(e);}finally{busy.value=false;}}
function followup(type:'generation'|'evaluation'){followKind.value=type;requirements.value=type==='evaluation'?'按当前启用规则重新评测，独立保存本轮证据与报告。':'';error.value='';followDialog.value?.showModal();}
async function submit(){if(!detail.value)return;busy.value=true;error.value='';try{const r=await api<{items:AutomationTask[]}>(`/automation/tasks/${detail.value.id}/followup`,{method:'POST',body:JSON.stringify({requirements:requirements.value,kind:followKind.value})});followDialog.value?.close();await refresh();go(`/tasks/${r.items[0].id}`);}catch(e){error.value=message(e);}finally{busy.value=false;}}
const viewportNames:Record<string,string>={desktop:'PC',mobile:'移动端',business:'业务'};
const qualityNames={passed:'达到标准',failed:'需要改进',unverified:'有待验证'};
</script>
<template>
<template v-if="!id"><header class="page-header"><div><h1>{{reports?'评测报告':'任务中心'}}</h1></div><div class="toolbar-actions"><a v-if="reports" class="button secondary" href="#/legacy-evaluations"><FileText :size="16" />历史评测记录</a><a class="button primary" href="#/resources"><Play :size="16" />{{reports?'选择站点评测':'从资源创建任务'}}</a></div></header>
<p v-if="!workspace.settings.enabled" class="alert info"><Clock3 :size="17" /><span>自动执行已暂停，队列中的任务会保留。</span><a href="#/settings">前往设置<ArrowUpRight :size="15" /></a></p>
<div v-if="!reports" class="queue-summary"><div><span>生成执行</span><strong>{{active.filter(t=>t.kind==='generation').length}}<small>/ {{workspace.settings.generationConcurrency}}</small></strong></div><div><span>评测执行</span><strong>{{active.filter(t=>t.kind==='evaluation').length}}<small>/ {{workspace.settings.evaluationConcurrency}}</small></strong></div><div><span>排队中</span><strong>{{queued}}</strong></div><button :class="{highlight:pending}" @click="filter=filter==='attention'?'':'attention'"><span>需要处理</span><strong>{{pending}}</strong></button></div>
<section class="panel"><div class="table-toolbar"><label class="search-field"><Search :size="18" /><input v-model="query" :placeholder="reports?'搜索资源、站点或报告':'搜索资源、站点或任务'" aria-label="搜索任务" /></label><div class="toolbar-actions"><BaseSelect v-if="!reports" v-model="kind" class="compact-select" aria-label="任务类型"><option value="">全部类型</option><option value="generation">生成</option><option value="evaluation">评测</option></BaseSelect><BaseSelect v-model="filter" class="compact-select" aria-label="任务状态"><option value="">全部状态</option><option value="attention">需要处理</option><option v-for="(name,key) in taskStatusNames" :key="key" :value="key">{{name}}</option></BaseSelect><button class="icon-button" aria-label="刷新任务" @click="load"><RefreshCw :size="17" /></button></div></div><p v-if="error||workspace.error" class="alert error">{{error||workspace.error}}</p>
<div class="table-scroll"><table class="task-table"><thead><tr><th>资源 / 生成站</th><th v-if="!reports">类型</th><th>范围</th><th>执行状态</th><th v-if="reports">质量 / 评分</th><th>用量费用</th><th>创建时间</th><th /></tr></thead><tbody><tr v-for="task in rows" :key="task.id"><td><a class="task-title" :href="`#/tasks/${task.id}`">{{task.resourceName}}</a><span class="table-subtitle">{{task.siteUrl||scenarios[task.scenario]}}</span></td><td v-if="!reports">{{task.kind==='generation'?'生成':'评测'}}</td><td>{{scopeName(task.scope)}}</td><td><span class="status-badge" :class="task.status"><i />{{taskStatusNames[task.status]}}</span><span v-if="task.delivery" class="table-subtitle">交付：{{({queued:'排队中',running:'迁移中',uncertain:'待核查',verifying:'核验中',completed:'核验完成',failed:'未完成'})[task.delivery.status]}}</span></td><td v-if="reports"><span v-if="task.report" :class="task.report.quality==='passed'?'success-text':'warning-text'">{{qualityNames[task.report.quality]}}</span><span v-else class="text-muted">报告尚未生成</span><span v-if="task.report" class="table-subtitle">{{task.report.scores.map(s=>`${viewportNames[s.viewport]} ${s.value??'未验证'}`).join(' · ')}}</span></td><td>{{task.usage?.requests?(task.usage.priced?`¥ ${task.usage.knownCny.toFixed(4)}`:'待核算'):'待采集'}}<span v-if="task.usage?.missing" class="table-subtitle">{{task.usage.missing}} 条待核算</span></td><td class="date-cell">{{formatDate(task.createdAt)}}</td><td><a class="text-action" :href="`#/tasks/${task.id}`">{{reports?'查看报告':'详情'}}<ArrowUpRight :size="14" /></a></td></tr></tbody></table></div><div v-if="!rows.length" class="empty-state"><FileText v-if="reports" :size="30" /><Clock3 v-else :size="30" /><h2>{{reports?'暂无评测报告':'暂无任务'}}</h2><p>{{reports?'从资源的生成站发起独立评测':'先在资源库中选择一个或多个资源'}}</p></div><footer class="table-footer"><span>共 {{list.length}} 项</span><div class="pagination"><button class="icon-button" :disabled="page<=1" aria-label="上一页" @click="page--"><ChevronLeft :size="17" /></button><span>{{page}} / {{pages}}</span><button class="icon-button" :disabled="page>=pages" aria-label="下一页" @click="page++"><ChevronRight :size="17" /></button></div></footer></section></template>
<template v-else-if="detail"><a class="back-link" :href="detail.kind==='evaluation'?'#/reports':'#/tasks'"><ArrowLeft :size="16" />{{detail.kind==='evaluation'?'评测报告':'任务中心'}}</a><header class="page-header"><div><h1>{{detail.resourceName}}</h1><p>{{detail.kind==='generation'?'生成任务':'评测任务'}} · {{scopeName(detail.scope)}} · {{formatDate(detail.createdAt)}}</p></div><div class="toolbar-actions"><button v-if="!detail.stopped||['queued','following-up'].includes(detail.status)" class="button secondary" :disabled="busy||detail.status==='cancelling'" @click="cancel"><Ban :size="16" />{{detail.status==='cancelling'?'正在停止':'取消任务'}}</button><button v-if="detail.stopped&&['pending','failed','interrupted'].includes(detail.status)" class="button primary" :disabled="busy" @click="resume"><Play :size="16" />AI 接管 / 恢复</button><template v-if="detail.stopped&&detail.generatedSiteId&&!['queued','following-up','cancelling'].includes(detail.status)"><button class="button secondary" :disabled="busy" @click="followup('generation')"><Send :size="16" />{{detail.kind==='evaluation'?'跟进生成':'提交跟进'}}</button><button class="button primary" :disabled="busy||!detail.siteUrl" @click="followup('evaluation')"><FileText :size="16" />{{detail.kind==='evaluation'?'重新评测':'发起评测'}}</button></template></div></header>
<div v-if="['pending','interrupted'].includes(detail.status)&&!detail.stopped" class="alert info"><span>先检查 Kooboo 原会话 / 本机执行进程，确认停止后再释放执行名额。</span><button class="button secondary small" :disabled="busy" @click="confirmStopped">确认原执行已停止</button></div><div class="task-detail-meta"><span class="status-badge" :class="detail.status"><i />{{taskStatusNames[detail.status]}}</span><a :href="`#/resources/${detail.resourceId}`">查看资源<ArrowUpRight :size="14" /></a><a v-if="detail.siteUrl" :href="detail.siteUrl" target="_blank" rel="noopener noreferrer">打开站点<ExternalLink :size="14" /></a><a v-if="detail.parentId" :href="`#/tasks/${detail.parentId}`">上一轮任务<ArrowUpRight :size="14" /></a></div>
<p v-if="detail.error&&!detail.interruption" class="alert" :class="detail.status==='pending'?'info':'error'" role="alert"><CircleAlert :size="18" />{{detail.error}}</p><p v-if="error" class="alert error">{{error}}</p>
<section v-if="detail.interruption" class="panel settings-panel interruption-panel"><h2>任务已中断</h2><p>{{detail.interruption.reason}}</p><h3>下一步</h3><ul><li v-for="step in detail.interruption.nextSteps" :key="step">{{step}}</li></ul><p>{{detail.interruption.resumeFrom}}</p><details v-if="detail.interruption.attempted.length"><summary>已尝试的处理</summary><pre class="resource-description">{{detail.interruption.attempted.join('\n\n')}}</pre></details></section>
<p v-if="detail.status==='following-up'" class="alert info"><LoaderCircle class="spin" :size="17" />AI 正在自主跟进当前问题；你可以离开此页面，系统会继续推进并保留结果。</p>
<div v-if="detail.followup" class="task-detail-meta"><span>AI 跟进 {{detail.followup.attempts}} / {{detail.followup.policy.maxAttempts}} 次</span><span>累计执行 {{Math.round(((detail.followup.elapsedMs||0)+(detail.followup.activeElapsedMs||0))/1000)}} / {{detail.followup.policy.maxMinutes*60}} 秒</span><span v-if="detail.followup.lastAction">{{detail.followup.lastAction.reason}}</span></div>
<a v-if="detail.evaluationTaskId" class="button secondary" :href="`#/tasks/${detail.evaluationTaskId}`"><FileText :size="16" />查看后续评测</a>
<TaskUsage :summary="detail.usage" :entries="usageEntries"/><TaskDelivery :task="detail" @changed="load"/>
<div class="segmented view-tabs"><button v-if="detail.kind==='evaluation'" :class="{selected:tab==='report'}" @click="tab='report'">评测结果</button><button :class="{selected:tab==='execution'||detail.kind==='generation'&&tab==='report'}" @click="tab='execution'">执行过程</button><button :class="{selected:tab==='input'}" @click="tab='input'">本轮输入</button><button v-if="detail.rule" :class="{selected:tab==='rule'}" @click="tab='rule'">规则快照</button></div>
<template v-if="detail.kind==='evaluation'&&tab==='report'"><div v-if="!detail.report" class="panel empty-state"><FileText :size="30" /><h2>尚未生成有效报告</h2><p>查看执行状态与上下文；无报告时不显示为零分</p></div><template v-else><div class="report-score-grid"><section v-for="item in detail.report.scores" :key="item.viewport" class="panel report-score"><span>{{viewportNames[item.viewport]}}</span><strong>{{item.value??'—'}}</strong><small>{{item.value===null?'未验证':'按本轮规则计算'}}</small></section><section class="panel report-verdict"><span>质量结论</span><h2 :class="detail.report.quality==='passed'?'success-text':'warning-text'">{{qualityNames[detail.report.quality]}}</h2></section></div><section class="panel settings-panel"><h2>评测结论</h2><p class="report-summary">{{detail.report.summary}}</p><div class="table-scroll"><table class="task-table"><thead><tr><th>指标</th><th>视口</th><th>评分</th><th>依据</th></tr></thead><tbody><tr v-for="item in detail.report.assessments" :key="item.criterionId+item.viewport"><td>{{detail.rule?.criteria.find(c=>c.id===item.criterionId)?.label||item.criterionId}}</td><td>{{viewportNames[item.viewport]}}</td><td>{{item.score??'未验证'}}</td><td class="wrapping-cell">{{item.reason}}<div class="evidence-links"><a v-for="file in item.evidence" :key="file" :href="`/api/v1/automation/reports/${detail.id}/artifacts/${file}`" target="_blank">{{file.slice(0,8)}}<ExternalLink :size="12" /></a></div></td></tr></tbody></table></div></section>
<section class="panel settings-panel"><h2>问题清单</h2><p v-if="!detail.report.issues.length" class="text-muted">没有已取证的问题；仍需结合覆盖情况判断</p><article v-for="(issue,index) in detail.report.issues" :key="index" class="report-issue"><span class="status-badge" :class="issue.severity==='minor'?'pending':'failed'">{{issue.severity}}</span><h3>{{issue.title}}</h3><p>{{issue.detail}}</p><div class="evidence-links"><a v-for="file in issue.evidence" :key="file" :href="`/api/v1/automation/reports/${detail.id}/artifacts/${file}`" target="_blank">查看证据<ExternalLink :size="12" /></a></div></article></section>
<section class="panel settings-panel"><h2>覆盖范围</h2><div class="coverage-grid"><div v-for="item in [{key:'verified' as const,label:'已验证'},{key:'unverified' as const,label:'未验证'},{key:'outOfScope' as const,label:'范围之外'}]" :key="item.key"><h3>{{item.label}}</h3><ul v-if="detail.report.coverage[item.key].length"><li v-for="(text,index) in detail.report.coverage[item.key]" :key="index">{{text}}</li></ul><p v-else class="text-muted">—</p></div></div></section>
<section class="panel settings-panel"><h2>证据材料</h2><div class="evidence-grid"><a v-for="file in detail.report.artifacts.filter(f=>f.type==='image/png')" :key="file.id" :href="`/api/v1/automation/reports/${detail.id}/artifacts/${file.name}`" target="_blank"><img :src="`/api/v1/automation/reports/${detail.id}/artifacts/${file.name}`" loading="lazy" :alt="`本轮截图证据 ${file.name}`" /><span>{{file.name.slice(0,8)}}</span></a></div><a class="text-action" :href="`/api/v1/automation/reports/${detail.id}`" target="_blank">读取完整报告 JSON<ExternalLink :size="14" /></a></section></template></template>
<template v-if="tab==='execution'||(detail.kind==='generation'&&tab==='report')"><section class="panel settings-panel"><h2>执行记录</h2><ol class="execution-log"><li v-for="event in events" :key="event.seq"><time>{{formatDate(event.time)}}</time><pre>{{event.message}}</pre></li></ol><p v-if="!events.length" class="text-muted">暂无执行记录</p></section><section v-if="detail.context" class="panel settings-panel"><h2>最近会话上下文</h2><pre class="resource-description">{{detail.context}}</pre></section></template>
<section v-if="tab==='input'" class="panel settings-panel"><h2>输入版本 {{version?.revision}}</h2><pre class="resource-description">{{detail.message}}</pre><p class="text-muted">输入版本 ID：{{detail.versionId}}</p><p v-if="detail.threadId" class="text-muted">执行会话：{{detail.threadId}}</p><p v-if="detail.model" class="text-muted">模型：{{detail.model.name}}</p></section>
<section v-if="tab==='rule'&&detail.rule" class="panel settings-panel"><h2>{{detail.rule.name}}</h2><p class="text-muted">{{detail.rule.hash}}</p><pre class="resource-description">{{detail.rule.sop}}</pre><pre v-if="detail.rule.references" class="resource-description">{{detail.rule.references}}</pre><div v-for="c in detail.rule.criteria" :key="c.id" class="version-entry"><strong>{{c.label}} · {{c.weight}}%{{c.required?' · 必过项':''}}</strong><p>{{c.instruction}}</p></div></section>
</template><div v-else class="empty-state"><p>{{error||'正在读取任务…'}}</p></div>
<dialog ref="followDialog" class="modal"><form @submit.prevent="submit"><div class="modal-head"><h2>{{followKind==='evaluation'?'重新评测':'提交跟进'}}</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="followDialog?.close()"><X :size="20" /></button></div><p class="text-muted">继续使用选定生成站，新任务会重新进入队列。</p><label class="field"><span>{{followKind==='evaluation'?'评测要求':'跟进消息'}}</span><textarea v-model="requirements" class="input" rows="6" required /></label><p v-if="error" class="alert error">{{error}}</p><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="followDialog?.close()">取消</button><button class="button primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16" /><Send v-else :size="16" />加入队列</button></div></form></dialog>
</template>
